## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Is Asked
Tests per-key streaming stats with independent sliding windows, combining deques, hashtables, and a heap with lazy expirations. It mirrors real services that analyze per-entity signals under time constraints.

## Key Concepts
- Per-key deques for time-bounded data
- Hash map for key -> stats
- Max-heap with lazy deletion to keep top averages up-to-date
- Expiration handling driven by currentTime

## Code Example
```javascript
class PerKeyRollingStats {
  constructor(W) { this.W = W; this.map = new Map(); this.heap = new MaxHeap(); }
  add(key, value, ts) {
    let rec = this.map.get(key) || { dq: [], sum: 0 };
    rec.dq.push([ts, value]);
    rec.sum += value;
    while (rec.dq.length && rec.dq[0][0] < ts - this.W) {
      const [t, v] = rec.dq.shift();
      rec.sum -= v;
    }
    this.map.set(key, rec);
    const avg = rec.sum / rec.dq.length;
    this.heap.push({ key, avg, validAt: ts, len: rec.dq.length });
  }
  topK(currentTime, K) {
    const res = [];
    while (res.length < K) {
      const top = this.heap.pop();
      if (!top) break;
      const rec = this.map.get(top.key);
      const avg = rec && rec.dq.length ? rec.sum / rec.dq.length : -Infinity;
      if (top.avg !== avg) continue; // stale entry
      res.push(top.key);
    }
    // optional: reinsert from a temp to preserve heap state
    return res;
  }
}
```

## Follow-up Questions
- How would you handle a very large number of keys with memory constraints?
- How would you adapt to variable window sizes per key or out-of-order events?

## Why This Is Asked
This problem tests the integration of fundamental data structures—arrays, linked lists, hashmaps, and heaps—to solve a streaming scenario with sliding window deduplication and real-time ranking.

## Key Concepts
- Sliding window deduplication per (user_id, action) using a hashmap with timestamp tracking
- Per-user score aggregation maintained in a hashmap for O(1) updates
- Global top-K ranking via max-heap with O(log K) insertion/deletion and lazy invalidation
- Efficient expiration handling using linked lists and amortized cleanup strategies

## Code Example
```javascript
class EventProcessor {
  constructor(W) {
    this.W = W;
    this.latestByUserAction = new Map(); // (user_id,action) -> timestamp
    this.userTotals = new Map(); // user_id -> total_score
    this.userEvents = new Map(); // user_id -> linked list of (timestamp, score)
    this.maxHeap = new MaxHeap(); // (total_score, user_id)
  }

  addEvent(event) {
    const key = `${event.user_id}:${event.action}`;
    const latest = this.latestByUserAction.get(key);

    if (!latest || event.ts - latest > this.W) {
      // Update dedup map
      this.latestByUserAction.set(key, event.ts);

      // Update user total
      const currentTotal = this.userTotals.get(event.user_id) || 0;
      const newTotal = currentTotal + event.score;
      this.userTotals.set(event.user_id, newTotal);

      // Add to user's event list
      if (!this.userEvents.has(event.user_id)) {
        this.userEvents.set(event.user_id, new LinkedList());
      }
      this.userEvents.get(event.user_id).push({ts: event.ts, score: event.score});

      // Update heap
      this.maxHeap.insert({score: newTotal, user: event.user_id});
    }
  }

  getTopK(k, now) {
    this.expire(now);
    return this.maxHeap.getTopK(k);
  }

  expire(now) {
    for (const [userId, events] of this.userEvents) {
      while (events.length > 0 && now - events.head.ts > this.W) {
        const expired = events.shift();
        const currentTotal = this.userTotals.get(userId);
        const newTotal = currentTotal - expired.score;
        this.userTotals.set(userId, newTotal);

        if (newTotal > 0) {
          this.maxHeap.insert({score: newTotal, user: userId});
        }
      }
    }
  }
}
```

## Complexity Analysis
**Time:** O(1) amortized per event for updates, O(log K) for top-K retrieval
**Space:** O(N) where N is number of active users plus events within window W

## Why This Is Asked

This question tests your ability to apply k-way merge algorithms to partially sorted data, a common scenario in data processing pipelines and external sorting. It emphasizes understanding how the number of runs (r) impacts both time complexity and memory usage, connecting theoretical concepts with practical implementation.

## Key Concepts

- **k-way merge**: Efficient merging of multiple sorted sequences
- **Run detection**: Identifying sorted segments in a single linear pass
- **Min-heap**: Priority queue for selecting minimum elements efficiently
- **Complexity analysis**: O(n log r) time, O(r) auxiliary space
- **Edge cases**: Empty input, duplicate elements, and single-run scenarios

## Code Example

```javascript
class MinHeap {
  constructor() { 
    this.heap = []; 
  }

  size() { 
    return this.heap.length; 
  }

  push(item) {
    this.heap.push(item);
    this._heapifyUp(this.heap.length - 1);
  }

  pop() {
    if (this.heap.length === 0) return null;
    const min = this.heap[0];
    const last = this.heap.pop();
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this._heapifyDown(0);
    }
    return min;
  }

  _heapifyUp(index) { /* implementation */ }
  _heapifyDown(index) { /* implementation */ }
}

function kWayMerge(arr) {
  // Edge case: empty input
  if (arr.length === 0) return [];

  // Detect runs
  const runs = [];
  let start = 0;

  for (let i = 1; i <= arr.length; i++) {
    if (i === arr.length || arr[i-1] > arr[i]) {
      runs.push({start, end: i-1, index: start});
      start = i;
    }
  }

  // Edge case: r=1 (already sorted)
  if (runs.length === 1) return arr.slice();

  // Initialize heap with first elements
  const heap = new MinHeap();
  const result = [];

  runs.forEach((run, i) => {
    heap.push({value: arr[run.index], runId: i});
  });

  // Merge process
  while (heap.size() > 0) {
    const {value, runId} = heap.pop();
    result.push(value);

    const run = runs[runId];
    if (run.index < run.end) {
      run.index++;
      heap.push({value: arr[run.index], runId});
    }
  }

  return result;
}
```

